//! Plugin management: loading, listing, adding, removing and updating
//! plugins stored in `$HOME/.DataSurgeon/plugins.json`.

mod http;

use serde::{Deserialize, Serialize};
use std::env;
use std::fs::{File, OpenOptions};
use std::io::{self, Read, Write};
use std::process;

/// A single plugin definition.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Plugin {
    pub arg_long_name: String,
    pub help_message: String,
    pub content_type: String,
    pub source_url: String,
    pub version: String,
    pub regex: String,
}

/// Number of times the confirmation prompt can recurse before the
/// process gives up (mirrors the stack exhaustion of the reference tool).
const MAX_PROMPT_DEPTH: usize = 47611;

/// Returns the absolute path of the plugin file
pub fn get_plugin_path() -> String {
    let home_directory: String =
        env::var("HOME")
                            .expect("Home directory not found. Failed to read environmental variable: `HOME`.");
    format!("{}/.DataSurgeon/plugins.json", home_directory)
}

fn flush_stdout() {
    let _ = io::stdout().flush();
}

fn stack_exhausted() -> ! {
    flush_stdout();
    let _ = writeln!(
        io::stderr(),
        "\nthread 'main' ({}) has overflowed its stack\nfatal runtime error: stack overflow, aborting",
        process::id()
    );
    process::abort();
}

/// Asks the user whether the program should exit. Returns when the
/// user answers `n`, terminates the process on `y`.
fn ask_to_exit() {
    let mut depth: usize = 0;
    loop {
        depth += 1;
        if depth > MAX_PROMPT_DEPTH {
            stack_exhausted();
        }
        println!("[+] Do you want to exit? (y/n): ");
        let mut answer = String::new();
        let _ = io::stdin().read_line(&mut answer);
        match answer.trim().to_lowercase().as_str() {
            "y" => process::exit(1),
            "n" => return,
            _ => println!("[-] Invalid input. Please enter 'y' or 'n'."),
        }
    }
}

/// Loads all plugins from the plugin file.
pub fn load_plugins() -> Vec<Plugin> {
    let path = get_plugin_path();
    let mut file = match File::open(&path) {
        Ok(f) => f,
        Err(_) => {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", path);
            return Vec::new();
        }
    };
    let mut contents = String::new();
    if file.read_to_string(&mut contents).is_err() {
        println!("[-] Error: Failed to read from plugins.json file.");
        ask_to_exit();
        return Vec::new();
    }
    match serde_json::from_str::<Vec<Plugin>>(&contents) {
        Ok(plugins) => plugins,
        Err(_) => {
            println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
            ask_to_exit();
            Vec::new()
        }
    }
}

/// Writes the plugins back to the plugin file. Returns false on failure.
fn save_plugins(plugins: &[Plugin]) -> bool {
    let path = get_plugin_path();
    let mut file = match OpenOptions::new().write(true).truncate(true).open(&path) {
        Ok(f) => f,
        Err(_) => {
            println!("[-] Error: Failed to open plugins.json file.");
            return false;
        }
    };
    let data = match serde_json::to_string(plugins) {
        Ok(d) => d,
        Err(_) => {
            println!("[-] Error: Failed to serialize plugins.");
            return false;
        }
    };
    if file.write_all(data.as_bytes()).is_err() {
        println!("[-] Error: Failed to write to plugins.json file.");
        return false;
    }
    true
}

/// Normalizes a repository URL so that small differences (scheme,
/// letter case, trailing slashes) do not matter when comparing.
fn normalize_url(url: &str) -> String {
    url.trim_end_matches('/')
        .to_lowercase()
        .replace("https://", "")
        .replace("http://", "")
}

/// Prints a table with all installed plugins.
pub fn list_plugins() {
    let plugins = load_plugins();
    let path = get_plugin_path();
    if plugins.is_empty() {
        println!("No plugins found. Plugin File: {}", path);
        return;
    }
    println!("Plugin File: {}\n", path);
    let headers = ["Source URL", "Version", "Argument Long Name"];
    let mut widths = [headers[0].len(), headers[1].len(), headers[2].len()];
    for p in &plugins {
        widths[0] = widths[0].max(p.source_url.len());
        widths[1] = widths[1].max(p.version.len());
        widths[2] = widths[2].max(p.arg_long_name.len());
    }
    println!(
        "{:<w0$} | {:<w1$} | {:<w2$}",
        headers[0],
        headers[1],
        headers[2],
        w0 = widths[0],
        w1 = widths[1],
        w2 = widths[2]
    );
    for p in &plugins {
        println!(
            "{:<w0$} | {:<w1$} | {:<w2$}",
            p.source_url,
            p.version,
            p.arg_long_name,
            w0 = widths[0],
            w1 = widths[1],
            w2 = widths[2]
        );
    }
}

/// Builds the URL of the raw plugin file from the repository URL.
fn raw_plugin_url(url: &str) -> String {
    let raw = url.replace("github.com", "raw.githubusercontent.com");
    format!("{}/main/plugins.json", raw.trim_end_matches('/'))
}

/// Downloads the plugin definitions stored in the given repository.
fn download_plugins(url: &str) -> Vec<Plugin> {
    let raw_url = raw_plugin_url(url);
    match http::get(&raw_url) {
        Ok(response) => {
            if !(200..300).contains(&response.status) {
                println!(
                    "Error: Received a {} status code from the server.",
                    http::status_text(response.status)
                );
                process::exit(1);
            }
            let body = String::from_utf8_lossy(&response.body).into_owned();
            match serde_json::from_str::<Vec<Plugin>>(&body) {
                Ok(p) => p,
                Err(e) => {
                    println!(
                        "[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}",
                        e
                    );
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            println!(
                "[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}",
                e
            );
            process::exit(1);
        }
    }
}

/// Downloads and installs the plugins of a repository.
fn install_plugins(url: &str, updating: bool) {
    let mut plugins = load_plugins();
    let mut new_plugins = download_plugins(url);
    let single = new_plugins.len() == 1;
    for new_plugin in &new_plugins {
        for plugin in &plugins {
            if plugin.arg_long_name == new_plugin.arg_long_name {
                println!(
                    "[-] Error: Skipping Duplicate plugin found with arg_long_name: {}",
                    new_plugin.arg_long_name
                );
                if single {
                    return;
                }
            }
        }
    }
    let source_url = url.trim_end_matches('/').to_string();
    for p in new_plugins.iter_mut() {
        p.source_url = source_url.clone();
    }
    plugins.extend(new_plugins);
    if !save_plugins(&plugins) {
        return;
    }
    if updating {
        println!("[*] Updated Plugin: {}", url);
    } else {
        println!("[*] Download and added plugin: {}", url);
    }
}

/// Adds a plugin from a repository URL
pub fn add_plugin(url: &str) {
    install_plugins(url, false);
}

/// Removes every plugin installed from the given URL. Returns true when
/// at least one plugin was removed.
fn remove_matching(url: &str) -> bool {
    let mut plugins = load_plugins();
    let target = normalize_url(url);
    let before = plugins.len();
    plugins.retain(|p| normalize_url(&p.source_url) != target);
    if plugins.len() == before {
        return false;
    }
    save_plugins(&plugins)
}

/// Removes a plugin given its repository URL
pub fn remove_plugin(url: &str) {
    if remove_matching(url) {
        println!("[*] Removed plugin: {}", url);
    }
}

fn update_single(url: &str) {
    let plugins = load_plugins();
    let target = normalize_url(url);
    if !plugins.iter().any(|p| normalize_url(&p.source_url) == target) {
        println!("[-] Error: No existing plugin found with the given URL: {}", url);
        process::exit(1);
    }
    remove_matching(url);
    install_plugins(url, true);
}

/// Updates one plugin (or all of them when `url` is "all")
pub fn update_plugin(url: &str) {
    if url.to_lowercase() == "all" {
        let plugins = load_plugins();
        for plugin in plugins {
            update_single(&plugin.source_url);
        }
    } else {
        update_single(url);
    }
}
EOF
echo ok"}

