use url::{Host, Url};

pub struct Response {
    pub status: u16,
    pub body: Vec<u8>,
}

/// Returns the canonical text of an HTTP status code, e.g. "404 Not Found".
pub fn status_text(code: u16) -> String {
    let reason = match code {
        100 => "Continue",
        101 => "Switching Protocols",
        102 => "Processing",
        200 => "OK",
