        506 => "Variant Also Negotiates",
        507 => "Insufficient Storage",
        508 => "Loop Detected",
        510 => "Not Extended",
        511 => "Network Authentication Required",
        _ => "<unknown status code>",
    };
    format!("{} {}", code, reason)
}

fn resolve(url: &Url) -> Result<Vec<SocketAddr>, String> {
    let port = url.port_or_known_default().unwrap_or(80);
    let addrs: Vec<SocketAddr> = match url.host() {
        Some(Host::Ipv4(ip)) => vec![SocketAddr::new(ip.into(), port)],
        Some(Host::Ipv6(ip)) => vec![SocketAddr::new(ip.into(), port)],
        Some(Host::Domain(d)) => match (d, port).to_socket_addrs() {
            Ok(a) => a.collect(),
            Err(e) => {
                return Err(format!(
                    "error sending request for url ({}): error trying to connect: dns error: {}",
                    url.as_str(),
                    e
                ))
            }
        },
        None => {
            return Err(format!(
                "builder error for url ({}): URL scheme is not allowed",
                url.as_str()
            ))
        }
    };
    Ok(addrs)
}

fn connect(url: &Url) -> Result<TcpStream, String> {
    let addrs = resolve(url)?;
    let mut last_err: Option<std::io::Error> = None;
    for addr in addrs {
        match TcpStream::connect_timeout(&addr, Duration::from_secs(30)) {
            Ok(s) => return Ok(s),
            Err(e) => last_err = Some(e),
        }
    }
    let msg = match last_err {
        Some(e) => e.to_string(),
        None => "no addresses".to_string(),
    };
    Err(format!(
        "error sending request for url ({}): error trying to connect: tcp connect error: {}",
        url.as_str(),
        msg
    ))
}

fn find_header_end(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n")
}

fn decode_chunked(mut data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    loop {
        let line_end = match data.windows(2).position(|w| w == b"\r\n") {
            Some(p) => p,
            None => break,
        };
        let size_str = String::from_utf8_lossy(&data[..line_end]).to_string();
        let size_str = size_str.split(';').next().unwrap_or("").trim().to_string();
        let size = match usize::from_str_radix(&size_str, 16) {
            Ok(s) => s,
            Err(_) => break,
        };
        data = &data[line_end + 2..];
        if size == 0 {
            break;
        }
        let take = size.min(data.len());
        out.extend_from_slice(&data[..take]);
        data = &data[take..];
        if data.len() >= 2 {
            data = &data[2..];
        }
    }
    out
}

fn request(url: &Url) -> Result<(u16, Vec<(String, String)>, Vec<u8>), String> {
    if url.scheme() == "https" {
        // TLS is not available; behave like a failed connection attempt.
        let _ = resolve(url)?;
        return Err(format!(
            "error sending request for url ({}): error trying to connect: tls handshake failed",
            url.as_str()
        ));
    }
    let mut stream = connect(url)?;
    let _ = stream.set_read_timeout(Some(Duration::from_secs(30)));
    let mut path = url.path().to_string();
    if let Some(q) = url.query() {
        path.push('?');
        path.push_str(q);
    }
    let host = match (url.host_str(), url.port()) {
        (Some(h), Some(p)) => format!("{}:{}", h, p),
        (Some(h), None) => h.to_string(),
        _ => String::new(),
    };
    let req = format!(
        "GET {} HTTP/1.1\r\naccept: */*\r\nhost: {}\r\nconnection: close\r\n\r\n",
        path, host
    );
    let send_err = |e: std::io::Error| {
        format!("error sending request for url ({}): {}", url.as_str(), e)
    };
    stream.write_all(req.as_bytes()).map_err(send_err)?;
    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).map_err(send_err)?;
    let header_end = match find_header_end(&raw) {
        Some(p) => p,
        None => {
            return Err(format!(
                "error sending request for url ({}): connection closed before message completed",
                url.as_str()
            ))
        }
    };
    let head = String::from_utf8_lossy(&raw[..header_end]).to_string();
    let mut lines = head.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    let status: u16 = status_line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);
    let mut headers = Vec::new();
    for l in lines {
        if let Some((k, v)) = l.split_once(':') {
            headers.push((k.trim().to_lowercase(), v.trim().to_string()));
        }
    }
    let mut body = raw[header_end + 4..].to_vec();
    let chunked = headers
        .iter()
        .any(|(k, v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));
    if chunked {
        body = decode_chunked(&body);
    } else if let Some((_, v)) = headers.iter().find(|(k, _)| k == "content-length") {
        if let Ok(len) = v.parse::<usize>() {
            body.truncate(len);
        }
    }
    Ok((status, headers, body))
}

/// Performs a GET request following redirects.
pub fn get(url_str: &str) -> Result<Response, String> {
    let mut url = match Url::parse(url_str) {
        Ok(u) => u,
        Err(e) => return Err(format!("builder error: {}", e)),
    };
    let mut redirects = 0;
    loop {
        if url.scheme() != "http" && url.scheme() != "https" {
            return Err(format!(
                "builder error for url ({}): URL scheme is not allowed",
                url.as_str()
            ));
        }
        let (status, headers, body) = request(&url)?;
        if matches!(status, 301 | 302 | 303 | 307 | 308) {
            if let Some((_, loc)) = headers.iter().find(|(k, _)| k == "location") {
                redirects += 1;
                if redirects > 10 {
                    return Err(format!(
                        "error following redirect for url ({}): too many redirects",
                        url.as_str()
                    ));
                }
                match url.join(loc) {
                    Ok(next) => {
                        url = next;
                        continue;
                    }
                    Err(_) => return Ok(Response { status, body }),
                }
            }
        }
        return Ok(Response { status, body });
    }
}
