//! DataSurgeon (ds): extracts sensitive information (emails, hashes,
//! IP addresses, urls, ...) from files, directories or standard input.

mod plugins;

use clap::{Arg, ArgAction, ArgMatches, Command};
use plugins::Plugin;
use regex::Regex;
use std::collections::{HashMap, HashSet};
use std::fs::{File, OpenOptions};
use std::io::{self, BufRead, BufReader, BufWriter, ErrorKind, Write};
use std::process;
use std::time::Instant;

/// Name displayed by `--version`
const APP_NAME: &str = "DataSurgeon: https://github.com/Drew-Alleman/DataSurgeon";
/// Current version
const APP_VERSION: &str = "1.2.8";
/// Text shown at the top of `--help`
const APP_ABOUT: &str =
    "Note: All extraction features (e.g: -i) work on a specified file (-f) or an output stream.";

/// Built-in extraction patterns: (content type / argument id, regex)
const BUILTIN_PATTERNS: [(&str, &str); 14] = [
    (
        "credit_card",
        r"\b\d{4}[- ]?\d{4}[- ]?\d{4}[- ]?\d{4}\b",
    ),
    (
        "email",
        r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,4}\b",
    ),
    (
        "url",
        r#"https?://[^\s"'(),.:;<>\[\]{}]+(?:\.[^\s"'(),.:;<>\[\]{}]+)*"#,
    ),
    (
        "ip_address",
        r"(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\b",
    ),
    (
        "ipv6_address",
        r"(?:[0-9a-fA-F]{1,4}:){1,7}[0-9a-fA-F]{1,4}|(?:[0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}|:(?:(?::[0-9a-fA-F]{1,4}){1,7}|:)",
