    ),
];

/// Converts a runtime string into a `'static` one (needed for clap ids
/// created from plugin definitions).
fn leak(s: &str) -> &'static str {
    Box::leak(s.to_string().into_boxed_str())
}

/// Creates a string option with an empty default value
fn string_option(id: &'static str, help: &'static str) -> Arg {
    Arg::new(id)
        .long(id)
        .help(help)
        .action(ArgAction::Set)
        .default_value("")
}

/// Creates a boolean flag
fn flag(id: &'static str, long: &'static str, help: &'static str) -> Arg {
    Arg::new(id).long(long).help(help).action(ArgAction::SetTrue)
}

/// Builds the command line interface, including the plugin arguments
fn build_command(plugins: &[Plugin]) -> Command {
    let mut command = Command::new(APP_NAME)
        .version(APP_VERSION)
        .about(APP_ABOUT)
        .arg(string_option("file", "File to extract information from").short('f'))
        .arg(string_option(
            "add",
            "Adds a plugin from a GitHub repository (e.g ds --add https://github.com/Drew-Alleman/ds-winreg-plugin/)",
        ))
        .arg(string_option(
            "update",
            "Updates a plugin from a GitHub repository. You can also use `ds --update all` to update all plugins. (e.g ds --update https://github.com/DataSurgeon-ds/ds-cve-plugin/)",
        ))
        .arg(string_option(
            "remove",
            "Removes a plugin from a GitHub repository (e.g ds --remove https://github.com/Drew-Alleman/ds-winreg-plugin/)",
        ))
        .arg(flag("list", "list", "List all added plugins"))
        .arg(
            flag(
                "clean",
                "clean",
                "Only displays the matched result, rather than the entire line",
            )
            .short('C'),
        )
        .arg(string_option(
            "directory",
            "Process all files found in the specified directory",
        ))
        .arg(flag("ignore", "ignore", "Silences error messages"))
        .arg(
            flag(
                "count",
                "line",
                "Displays the line number where the match occurred",
            )
            .short('l'),
        )
        .arg(
            flag(
                "thorough",
                "thorough",
                "Doesn't stop at first match (useful for -C if multiple unique matches are on the same line",
            )
            .short('T'),
        )
        .arg(
            flag(
                "display",
                "display",
                "Displays the filename assoicated with the content found (https://github.com/Drew-Alleman/DataSurgeon#reading-all-files-in-a-directory)",
            )
            .short('D'),
        )
        .arg(
            flag(
                "suppress",
                "suppress",
                "Suppress the 'Reading standard input' message when not providing a file",
            )
            .short('S'),
        )
        .arg(string_option(
            "drop",
            "Specify a regular expression to exclude certain patterns from the search. (e.g --drop \"^.{1,10}$\" will hide all matches not under 10 characters)",
        ))
        .arg(string_option(
            "filter",
            "Include only lines that match the specified regex. (e.g: '--filter ^error' will only include lines that start with the word 'error'",
        ))
        .arg(
            flag(
