/// Holds the state of an extraction run
struct DataSurgeon {
    filename: String,
    directory: String,
    output_file: String,
    clean: bool,
    is_output: bool,
    thorough: bool,
    hide_type: bool,
    display: bool,
    line_numbers: bool,
    ignore: bool,
    suppress: bool,
    time: bool,
    drop: Option<Regex>,
    filter: Option<Regex>,
    regex_map: HashMap<String, Regex>,
    stdout: BufWriter<io::Stdout>,
    file_writer: Option<BufWriter<File>>,
}

impl DataSurgeon {
    /// Flushes every pending output
    fn flush(&mut self) {
        let _ = self.stdout.flush();
        if let Some(w) = self.file_writer.as_mut() {
            let _ = w.flush();
        }
    }

    /// Flushes the pending output and terminates the process
    fn exit(&mut self, code: i32) -> ! {
        self.flush();
        process::exit(code);
    }

    /// Writes a message to standard output
    fn say(&mut self, message: &str) {
        if writeln!(self.stdout, "{}", message).is_err() {
            process::exit(1);
        }
    }

    /// Displays an error unless `--ignore` was supplied
    fn report(&mut self, message: String) {
        if !self.ignore {
            self.say(&message);
        }
    }

    /// Returns true if the content is not excluded by `--drop`
    fn allowed(&self, content: &str) -> bool {
        match &self.drop {
            Some(drop) => !drop.is_match(content),
            None => true,
        }
    }

    /// Opens the output file (appending) and writes the CSV header
    fn open_output_file(&mut self) {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.output_file);
        match file {
            Ok(f) => {
                let mut columns: Vec<&str> = Vec::new();
                if !self.hide_type {
                    columns.push("content_type");
                }
                if self.display {
                    columns.push("file");
                }
                if self.line_numbers {
                    columns.push("line");
                }
                columns.push("data");
                let mut writer = BufWriter::new(f);
                let _ = writeln!(writer, "{}", columns.join(", "));
                self.file_writer = Some(writer);
            }
            Err(e) => {
                let message = match e.kind() {
                    ErrorKind::NotFound => {
                        format!("[-] Failed to open output file: {}", self.filename)
                    }
                    ErrorKind::PermissionDenied => {
                        format!("[-] Permission denied for file: {}", self.filename)
                    }
                    _ => format!(
                        "[-] Failed to open output file: {}. Error: {}",
                        self.filename, e
                    ),
                };
                self.report(message);
                self.exit(1);
            }
        }
    }

    /// Writes one result either to the output file or to the terminal
    fn emit(&mut self, content_type: &str, content: &str, filename: &str, line_number: usize) {
        if self.is_output {
            let mut columns: Vec<String> = Vec::new();
            if !self.hide_type {
                columns.push(content_type.to_string());
            }
            if self.display {
                columns.push(filename.to_string());
            }
            if self.line_numbers {
                columns.push(line_number.to_string());
            }
            columns.push(content.to_string());
            if let Some(w) = self.file_writer.as_mut() {
                let _ = writeln!(w, "{}", columns.join(", "));
            }
            return;
        }
        let text = if !self.hide_type && !self.display && !self.line_numbers {
            format!("{}: {}", content_type, content)
        } else {
            let mut text = String::new();
            if !self.hide_type {
                text.push_str(content_type);
                text.push_str(", ");
            }
            if self.display {
                text.push_str("file: ");
                text.push_str(filename);
                text.push(' ');
            }
            text.push_str(content);
            if self.line_numbers {
                text.push_str(", line: ");
                text.push_str(&line_number.to_string());
            }
            text
        };
        self.say(&text);
    }

    /// Searches a single line for every requested pattern
    fn handle_line(&mut self, line: &str, line_number: usize, filename: &str) {
        if let Some(filter) = &self.filter {
            if !filter.is_match(line) {
                return;
            }
        }
        let regex_map = std::mem::take(&mut self.regex_map);
        self.search_line(&regex_map, line, line_number, filename);
        self.regex_map = regex_map;
    }

    fn search_line(
        &mut self,
        regex_map: &HashMap<String, Regex>,
        line: &str,
        line_number: usize,
        filename: &str,
    ) {
        let mut seen: HashSet<&str> = HashSet::new();
        for (content_type, regex) in regex_map.iter() {
            for found in regex.find_iter(line) {
                if !self.clean && self.allowed(line) {
                    self.emit(content_type, line, filename, line_number);
                    if !self.thorough {
                        return;
                    }
                }
                let content = found.as_str();
                if self.allowed(content) && seen.insert(content) {
                    self.emit(content_type, content, filename, line_number);
                    if !self.thorough {
                        return;
                    }
                }
            }
        }
    }

    /// Reads every line of the reader and searches it
    fn handle_reader<R: BufRead>(&mut self, reader: R, filename: &str) {
        let mut line_number: usize = 0;
        for line in reader.lines() {
            if let Ok(line) = line {
                line_number += 1;
                self.handle_line(&line, line_number, filename);
            }
        }
    }

    /// Opens and processes a file. Returns false if the file could not be opened.
    fn handle_file(&mut self, path: &str) -> bool {
        match File::open(path) {
            Ok(file) => {
                self.handle_reader(BufReader::new(file), path);
                true
            }
            Err(e) => {
                let message = match e.kind() {
                    ErrorKind::NotFound => format!("[-] File not found: {}", path),
                    ErrorKind::PermissionDenied => {
                        format!("[-] Permission denied for file: {}", path)
                    }
                    _ => format!("[-] Error opening file: {}. Error: {}", path, e),
                };
                self.report(message);
                false
            }
        }
    }

    /// Processes every regular file found in the directory (recursively)
    fn handle_directory(&mut self) {
        let directory = self.directory.clone();
        for entry in walkdir::WalkDir::new(&directory)
            .into_iter()
            .filter_map(|e| e.ok())
        {
            if entry.file_type().is_file() {
                let path = entry.path().to_string_lossy().into_owned();
                self.handle_file(&path);
            }
        }
    }

    /// Processes standard input
    fn handle_stdin(&mut self) {
        if !self.suppress {
            self.say("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        let stdin = io::stdin();
        let reader = stdin.lock();
        self.handle_reader(reader, "");
    }

    /// Runs the extraction
    fn process(&mut self) {
        let start = Instant::now();
        if self.is_output {
            self.open_output_file();
        }
        if !self.filename.is_empty() {
            let filename = self.filename.clone();
            if !self.handle_file(&filename) {
                self.exit(1);
            }
        } else if !self.directory.is_empty() {
            self.handle_directory();
        } else {
            self.handle_stdin();
        }
        if self.time {
            let seconds = start.elapsed().as_secs();
            let message = format!(
                "[*] Time elapsed: {:02}h:{:02}m:{:02}s",
                seconds / 3600,
                (seconds % 3600) / 60,
                seconds % 60
            );
            self.say(&message);
        }
        self.flush();
    }
}
