    s1, s2 = o1[1], o2[1]
    if sort:
        s1 = b'\n'.join(sorted(s1.split(b'\n'))); s2 = b'\n'.join(sorted(s2.split(b'\n')))
    ok = o1[0]==o2[0] and s1==s2 and o1[2]==o2[2] and x1==x2
